{"dir_path": "D:\", "file_name": "mcp_probe.py", "content": "import json, urllib.request

URL = "http://127.0.0.1:8090/mcp"
SID = None


def post(payload, notify=False):
    global SID
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(URL, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    req.add_header("Accept", "application/json, text/event-stream")
    if SID:
        req.add_header("Mcp-Session-Id", SID)
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            SID = r.headers.get("Mcp-Session-Id", SID)
            body = r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", "replace")
        print("HTTP", e.code, body[:500])
        return None
    if notify:
        return None
    # SSE or plain json
    if body.lstrip().startswith("event:") or body.lstrip().startswith("data:"):
        for line in body.splitlines():
            if line.startswith("data:"):
                return json.loads(line[5:].strip())
        return None
    return json.loads(body)


init = post({
    "jsonrpc": "2.0", "id": 1, "method": "initialize",
    "params": {"protocolVersion": "2024-11-05", "capabilities": {},
               "clientInfo": {"name": "agent-l", "version": "1.0"}}
})
print("== initialize ==")
print(json.dumps(init, ensure_ascii=False)[:400])

post({"jsonrpc": "2.0", "method": "notifications/initialized"}, notify=True)

tl = post({"jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {}})
print("== tools/list ==")
for t in (tl or {}).get("result", {}).get("tools", []):
    print("-", t.get("name"), "|", (t.get("description") or "")[:80])
    print("   schema:", json.dumps(t.get("inputSchema", {}), ensure_ascii=False)[:300])
"}

